// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { AlertTriangleIcon, CheckIcon, CopyIcon } from 'lucide-react'

import { DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import { CAPTIONS, CHANGED, EDITED, INPUT, ROWS, SECRET, SECRET_ERROR, SHA256 } from './script'

const HEX = '0123456789abcdef'
const INK = '#f5f5f7'
const SECRET_SLOT = 30

const build: Build = ({
  tl,
  q,
  qa,
  pos,
  step,
  final,
  move,
  click,
  type,
  scramble,
  wait,
  cursorOut,
}) => {
  const tabs = pos('tabs', 0, 0)
  const tabAt = (index: number) => {
    const tab = pos(`tab-${index}`, 0, 0)
    return { left: tab.x - tabs.x, width: tab.w }
  }
  tl.set(q('tab-pill'), tabAt(0), 0)

  step(0)
  move('input', { ax: 0.2, ay: 0.35, at: 0.2 })
  click('input')
  type('input-text', INPUT, { speed: 0.06 })
  tl.fromTo(
    qa('row'),
    { opacity: 0, y: 6 },
    { opacity: 1, y: 0, duration: 0.3, stagger: 0.06, ease: 'power2.out' },
    '>-0.1',
  )
  tl.fromTo(
    qa('hex-char'),
    { opacity: 0 },
    { opacity: 1, duration: 0.05, stagger: 0.006, ease: 'none' },
    '<',
  )
  ROWS.slice(1).forEach((row, offset) =>
    scramble(`digest-${offset + 1}`, row.before, {
      at: offset === 0 ? '<' : '<0.05',
      duration: 0.6,
      chars: HEX,
    }),
  )

  step(1, '+=0.6')
  move('input', { ax: 0.32, ay: 0.35 })
  click('input')
  tl.to(q('input-text'), { text: { value: EDITED, delimiter: '' }, duration: 0.15 })
  CHANGED.forEach((index, order) =>
    tl.to(
      q(`c-${index}`),
      { text: { value: SHA256.after[index] }, color: '#34d399', duration: 0.05 },
      order === 0 ? '>' : '<0.012',
    ),
  )
  tl.to(qa('hex-char'), { color: INK, duration: 0.8 }, '>+0.5')
  ROWS.slice(1).forEach((row, offset) =>
    scramble(`digest-${offset + 1}`, row.after, {
      at: offset === 0 ? `<-${CHANGED.length * 0.012 + 0.4}` : '<0.05',
      duration: 0.6,
      chars: HEX,
    }),
  )

  step(2, '+=0.8')
  move('tab-1')
  click('tab-1')
  tl.to(q('tab-pill'), { ...tabAt(1), duration: 0.35, ease: 'power3.inOut' }, '<')
  tl.to(q('tab-0'), { color: 'rgba(245,245,247,0.5)', duration: 0.2 }, '<')
  tl.to(q('tab-1'), { color: INK, duration: 0.2 }, '<')
  tl.to(q('secret-wrap'), { height: SECRET_SLOT, duration: 0.3, ease: 'power2.out' }, '<')
  tl.fromTo(q('secret'), { opacity: 0 }, { opacity: 1, duration: 0.25 }, '<')
  tl.to(qa('legacy-row'), { opacity: 0, duration: 0.25 }, '<')
  tl.to(q('hex-chars'), { opacity: 0, duration: 0.15 }, '<')
  tl.set(q('digest-0'), { opacity: 1 }, '>')
  ROWS.slice(0, 3).forEach((_, index) =>
    scramble(`digest-${index}`, SECRET_ERROR, { at: '<', duration: 0.4 }),
  )
  move('secret', { ax: 0.2 })
  click('secret')
  type('secret-text', SECRET, { speed: 0.06 })
  ROWS.slice(0, 3).forEach((row, index) =>
    scramble(`digest-${index}`, row.hmac ?? '', {
      at: index === 0 ? '>-0.1' : '<0.05',
      duration: 0.7,
      chars: HEX,
    }),
  )

  step(3, '+=0.7')
  move('copy-0', { dy: SECRET_SLOT })
  click('copy-0')
  tl.to(q('copy-0'), { opacity: 0, duration: 0.1 }, '<')
  tl.fromTo(
    q('done-0'),
    { opacity: 0, scale: 0.5 },
    { opacity: 1, scale: 1, duration: 0.25, ease: 'back.out(3)' },
    '<',
  )
  cursorOut('+=0.3')
  final()
  wait(1.4)
}

export default function Demo() {
  return (
    <DemoStage
      label="Hash Toolkit hashing hello world five ways, showing how one extra character changes almost every digit, then signing it with HMAC"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full flex-col gap-1.5">
          <div
            data-d="tabs"
            className="relative flex w-fit rounded-lg border border-line bg-white/[0.03] p-0.5"
          >
            <span
              data-d="tab-pill"
              className="absolute inset-y-0.5 left-0.5 w-10 rounded-md bg-white/10"
            />
            {['Hash', 'HMAC'].map((label, index) => (
              <span
                key={label}
                data-d={`tab-${index}`}
                className="relative px-2.5 py-0.5 text-[10.5px]"
                style={{ color: index === 0 ? INK : 'rgba(245,245,247,0.5)' }}
              >
                {label}
              </span>
            ))}
          </div>
          <div
            data-d="input"
            className="h-9 rounded-md border border-line-strong bg-canvas/80 px-2 py-1.5 font-mono text-[10.5px] text-ink"
          >
            <span data-d="input-text" />
          </div>
          <div data-d="secret-wrap" className="-mt-1.5 h-0 shrink-0 overflow-hidden">
            <div
              data-d="secret"
              className="mt-1.5 flex h-6 items-center rounded-md border border-line-strong bg-canvas/80 px-2 font-mono text-[10px] text-ink opacity-0"
            >
              <span
                data-d="secret-text"
                className="empty:before:text-muted empty:before:content-['HMAC_secret']"
              />
            </div>
          </div>
          <div className="flex flex-col gap-1">
            {ROWS.map((row, index) => (
              <div
                key={row.id}
                data-d={row.legacy ? 'row legacy-row' : 'row'}
                className="rounded border border-line bg-white/[0.03] px-1.5 py-1 opacity-0"
              >
                <div className="flex items-center justify-between">
                  <span className="flex items-center gap-1.5">
                    <span className="rounded border border-line-strong px-1 font-mono text-[9px] text-ink-soft">
                      {row.id}
                    </span>
                    {row.legacy ? (
                      <span className="flex items-center gap-0.5 text-[9px] text-amber">
                        <AlertTriangleIcon className="size-2.5" /> legacy
                      </span>
                    ) : null}
                  </span>
                  <span className="relative size-3 text-muted">
                    <span data-d={`copy-${index}`} className="absolute inset-0">
                      <CopyIcon className="size-3" />
                    </span>
                    <span
                      data-d={`done-${index}`}
                      className="absolute inset-0 text-[var(--accent)] opacity-0"
                    >
                      <CheckIcon className="size-3" />
                    </span>
                  </span>
                </div>
                <div className="relative mt-0.5 font-mono text-[8.5px] leading-[11px] text-ink">
                  {index === 0 ? (
                    <>
                      <code data-d="hex-chars" className="block break-all">
                        {[...SHA256.before].map((char, charIndex) => (
                          <span key={charIndex} data-d={`hex-char c-${charIndex}`}>
                            {char}
                          </span>
                        ))}
                      </code>
                      <code data-d="digest-0" className="absolute inset-0 break-all opacity-0" />
                    </>
                  ) : (
                    <code data-d={`digest-${index}`} className="block break-all">
                      {row.before}
                    </code>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
